/**
 * Canon reference solutions (the task's decls, then the function). Each passes canon check with
 * zero diagnostics and every test. Migrated to Canon v0.3 with canon fmt (&&, ||, ! and line
 * wrapping); the logic is unchanged.
 */
export const REFERENCE_CANON: Record<string, string> = {
  caesar_shift: "fn shift_char(c: String, k: Int) -> String {\n  let letters = split(\"abcdefghijklmnopqrstuvwxyz\", \"\")\n  let hits = filter(enumerate(letters), |p| p.1 == c)\n  return match first(hits) {\n    Some(p) => letters |> drop(((p.0 + k) % 26 + 26) % 26) |> first() |> unwrap_or(c),\n    None => c,\n  }\n}\n\nfn caesar_shift(s: String, k: Int) -> String {\n  return s\n    |> split(\"\")\n    |> map(|c| shift_char(c, k))\n    |> join(\"\")\n}\n",
  wrap_text: "fn wrap_text(s: String, width: Int) -> List[String] {\n  let words = filter(split(s, \" \"), |w| w != \"\")\n  var lines = []\n  var cur = \"\"\n  for w in words {\n    if cur == \"\" {\n      cur = w\n    } else if str_len(cur) + 1 + str_len(w) <= width {\n      cur = cur + \" \" + w\n    } else {\n      lines = append(lines, cur)\n      cur = w\n    }\n  }\n  if cur != \"\" {\n    lines = append(lines, cur)\n  }\n  return lines\n}\n",
  align_columns: "fn cell_at(row: List[String], j: Int) -> String {\n  return row\n    |> drop(j)\n    |> first()\n    |> unwrap_or(\"\")\n}\n\nfn pad(s: String, w: Int) -> String {\n  var out = s\n  while str_len(out) < w {\n    out = out + \" \"\n  }\n  return out\n}\n\nfn trim_end(s: String) -> String {\n  var cs = split(s, \"\")\n  while len(cs) > 0 && unwrap_or(last(cs), \"\") == \" \" {\n    cs = take(cs, len(cs) - 1)\n  }\n  return join(cs, \"\")\n}\n\nfn col_width(rows: List[List[String]], j: Int) -> Int {\n  return fold(rows, 0, |acc, r| max(acc, str_len(cell_at(r, j))))\n}\n\nfn render(row: List[String], widths: List[Int]) -> String {\n  let cells = map(zip(row, widths), |c, w| pad(c, w))\n  return trim_end(join(cells, \" | \"))\n}\n\nfn align_columns(rows: List[List[String]]) -> List[String] {\n  let ncols = fold(rows, 0, |acc, r| max(acc, len(r)))\n  let widths = map(range(0, ncols), |j| col_width(rows, j))\n  return map(rows, |r| render(r, widths))\n}\n",
  rle_compress: "fn runs(s: String) -> List[(String, Int)] {\n  var out = []\n  var cur = \"\"\n  var n = 0\n  for c in split(s, \"\") {\n    if n > 0 && c == cur {\n      n = n + 1\n    } else {\n      if n > 0 {\n        out = append(out, (cur, n))\n      }\n      cur = c\n      n = 1\n    }\n  }\n  if n > 0 {\n    out = append(out, (cur, n))\n  }\n  return out\n}\n\nfn piece(c: String, n: Int) -> String {\n  if n == 1 {\n    return c\n  }\n  return c + to_string(n)\n}\n\nfn rle_compress(s: String) -> String {\n  let enc = s\n    |> runs()\n    |> map(|c, n| piece(c, n))\n    |> join(\"\")\n  if str_len(enc) < str_len(s) {\n    return enc\n  }\n  return s\n}\n",
  rle_decode: "fn is_digit(c: String) -> Bool {\n  return c >= \"0\" && c <= \"9\"\n}\n\nfn repeat(c: String, n: Int) -> String {\n  var out = \"\"\n  var i = 0\n  while i < n {\n    out = out + c\n    i = i + 1\n  }\n  return out\n}\n\nfn flush(out: String, ch: String, digits: String) -> Result[String, String] {\n  if digits == \"\" {\n    return Ok(out + ch)\n  }\n  if (digits |> split(\"\") |> first() |> unwrap_or(\"\")) == \"0\" {\n    return Err(\"bad count for \" + ch)\n  }\n  return Ok(out + repeat(ch, unwrap_or(parse_int(digits), 0)))\n}\n\nfn rle_decode(s: String) -> Result[String, String] {\n  var out = \"\"\n  var ch = \"\"\n  var have = false\n  var digits = \"\"\n  for c in split(s, \"\") {\n    if is_digit(c) {\n      if !have {\n        return Err(\"missing character before count\")\n      }\n      digits = digits + c\n    } else {\n      if have {\n        out = try flush(out, ch, digits)\n      }\n      ch = c\n      have = true\n      digits = \"\"\n    }\n  }\n  if have {\n    out = try flush(out, ch, digits)\n  }\n  return Ok(out)\n}\n",
  pig_latin: "fn cluster_len(cs: List[String]) -> Int {\n  var i = 0\n  var prev = \"\"\n  var found = -1\n  for c in cs {\n    if found < 0 {\n      let vowel = contains([\"a\", \"e\", \"i\", \"o\", \"u\"], c) && !(c == \"u\" && prev == \"q\")\n      if vowel || c == \"y\" && i > 0 {\n        found = i\n      }\n    }\n    prev = c\n    i = i + 1\n  }\n  return found\n}\n\nfn pig_word(w: String) -> String {\n  let cs = split(w, \"\")\n  let n = cluster_len(cs)\n  if n == 0 {\n    return w + \"way\"\n  }\n  if n < 0 {\n    return w + \"ay\"\n  }\n  return join(drop(cs, n), \"\") + join(take(cs, n), \"\") + \"ay\"\n}\n\nfn pig_latin(s: String) -> String {\n  if s == \"\" {\n    return \"\"\n  }\n  return s\n    |> split(\" \")\n    |> map(|w| pig_word(w))\n    |> join(\" \")\n}\n",
  roman_to_int: "fn sym_val(c: String) -> Int {\n  return match c {\n    \"I\" => 1,\n    \"V\" => 5,\n    \"X\" => 10,\n    \"L\" => 50,\n    \"C\" => 100,\n    \"D\" => 500,\n    \"M\" => 1000,\n    _ => 0,\n  }\n}\n\nfn to_roman(n: Int) -> String {\n  let table = [(1000, \"M\"), (900, \"CM\"), (500, \"D\"), (400, \"CD\"), (100, \"C\"), (90, \"XC\"), (50, \"L\")]\n  let small = [(40, \"XL\"), (10, \"X\"), (9, \"IX\"), (5, \"V\"), (4, \"IV\"), (1, \"I\")]\n  var rest = n\n  var out = \"\"\n  for p in table {\n    while rest >= p.0 {\n      out = out + p.1\n      rest = rest - p.0\n    }\n  }\n  for p in small {\n    while rest >= p.0 {\n      out = out + p.1\n      rest = rest - p.0\n    }\n  }\n  return out\n}\n\nfn roman_to_int(s: String) -> Result[Int, String] {\n  if s == \"\" {\n    return Err(\"empty\")\n  }\n  let cs = split(s, \"\")\n  for c in cs {\n    if sym_val(c) == 0 {\n      return Err(\"invalid character: \" + c)\n    }\n  }\n  let vals = map(cs, |c| sym_val(c))\n  var total = 0\n  for p in zip(vals, append(drop(vals, 1), 0)) {\n    if p.0 < p.1 {\n      total = total - p.0\n    } else {\n      total = total + p.0\n    }\n  }\n  if total < 1 || total > 3999 || to_roman(total) != s {\n    return Err(\"not canonical\")\n  }\n  return Ok(total)\n}\n",
  anagram_groups: "fn sorted_key(w: String) -> String {\n  return w\n    |> split(\"\")\n    |> sort_by(|c| c)\n    |> join(\"\")\n}\n\nfn anagram_groups(words: List[String]) -> List[List[String]] {\n  return words\n    |> group_by(|w| sorted_key(w))\n    |> filter(|g| len(g.1) >= 2)\n    |> map(|g| g.1)\n}\n",
  find_all: "fn find_all(s: String, pat: String) -> List[Int] {\n  if pat == \"\" {\n    return []\n  }\n  let cs = split(s, \"\")\n  let ps = split(pat, \"\")\n  let m = len(ps)\n  return filter(range(0, len(cs) - m + 1), |i| take(drop(cs, i), m) == ps)\n}\n",
  heading_numbers: "fn hashes(cs: List[String]) -> Int {\n  var n = 0\n  var going = true\n  for c in cs {\n    if going && c == \"#\" {\n      n = n + 1\n    } else {\n      going = false\n    }\n  }\n  return n\n}\n\nfn heading_numbers(lines: List[String]) -> List[String] {\n  var a = 0\n  var b = 0\n  var c = 0\n  var out = []\n  for line in lines {\n    let cs = split(line, \"\")\n    let n = hashes(cs)\n    let sp = cs\n      |> drop(n)\n      |> first()\n      |> unwrap_or(\"\")\n    if n >= 1 && n <= 3 && sp == \" \" && len(cs) > n + 1 {\n      let title = join(drop(cs, n + 1), \"\")\n      if n == 1 {\n        a = a + 1\n        b = 0\n        c = 0\n        out = append(out, to_string(a) + \" \" + title)\n      } else if n == 2 {\n        b = b + 1\n        c = 0\n        out = append(out, to_string(a) + \".\" + to_string(b) + \" \" + title)\n      } else {\n        c = c + 1\n        out = append(out, to_string(a) + \".\" + to_string(b) + \".\" + to_string(c) + \" \" + title)\n      }\n    }\n  }\n  return out\n}\n",
  parse_duration: "fn unit_rank(c: String) -> Int {\n  return match c {\n    \"h\" => 1,\n    \"m\" => 2,\n    \"s\" => 3,\n    _ => 0,\n  }\n}\n\nfn unit_secs(r: Int) -> Int {\n  return match r {\n    1 => 3600,\n    2 => 60,\n    _ => 1,\n  }\n}\n\nfn parse_duration(s: String) -> Result[Int, String] {\n  if s == \"\" {\n    return Err(\"empty\")\n  }\n  var total = 0\n  var digits = \"\"\n  var last_rank = 0\n  for c in split(s, \"\") {\n    if c >= \"0\" && c <= \"9\" {\n      digits = digits + c\n    } else {\n      let r = unit_rank(c)\n      if r == 0 {\n        return Err(\"unknown unit: \" + c)\n      }\n      if digits == \"\" {\n        return Err(\"missing number before \" + c)\n      }\n      if r <= last_rank {\n        return Err(\"unit out of order: \" + c)\n      }\n      total = total + unwrap_or(parse_int(digits), 0) * unit_secs(r)\n      last_rank = r\n      digits = \"\"\n    }\n  }\n  if digits != \"\" {\n    return Err(\"missing unit\")\n  }\n  return Ok(total)\n}\n",
  parse_csv_line: "fn parse_csv_line(s: String) -> Result[List[String], String] {\n  var fields = []\n  var cur = \"\"\n  var state = 0\n  for p in enumerate(split(s, \"\")) {\n    let i = p.0\n    let c = p.1\n    if state == 0 || state == 1 {\n      if c == \",\" {\n        fields = append(fields, cur)\n        cur = \"\"\n        state = 0\n      } else if c == \"\\\"\" {\n        if state == 1 {\n          return Err(\"unexpected quote at \" + to_string(i))\n        }\n        state = 2\n      } else {\n        cur = cur + c\n        state = 1\n      }\n    } else if state == 2 {\n      if c == \"\\\"\" {\n        state = 3\n      } else {\n        cur = cur + c\n      }\n    } else if c == \"\\\"\" {\n      cur = cur + \"\\\"\"\n      state = 2\n    } else if c == \",\" {\n      fields = append(fields, cur)\n      cur = \"\"\n      state = 0\n    } else {\n      return Err(\"expected comma at \" + to_string(i))\n    }\n  }\n  if state == 2 {\n    return Err(\"unterminated quote\")\n  }\n  return Ok(append(fields, cur))\n}\n",
  parse_ipv4: "fn all_digits(cs: List[String]) -> Bool {\n  return len(filter(cs, |c| c >= \"0\" && c <= \"9\")) == len(cs)\n}\n\nfn part_ok(p: String) -> Bool {\n  let cs = split(p, \"\")\n  let n = len(cs)\n  if n < 1 || n > 3 || !all_digits(cs) {\n    return false\n  }\n  if n > 1 && unwrap_or(first(cs), \"\") == \"0\" {\n    return false\n  }\n  return unwrap_or(parse_int(p), 256) <= 255\n}\n\nfn parse_ipv4(s: String) -> Result[Int, String] {\n  let parts = split(s, \".\")\n  if len(parts) != 4 {\n    return Err(\"expected 4 parts\")\n  }\n  var total = 0\n  for p in parts {\n    if !part_ok(p) {\n      return Err(\"bad part: \" + p)\n    }\n    total = total * 256 + unwrap_or(parse_int(p), 0)\n  }\n  return Ok(total)\n}\n",
  compare_versions: "fn all_digits(cs: List[String]) -> Bool {\n  return len(filter(cs, |c| c >= \"0\" && c <= \"9\")) == len(cs)\n}\n\nfn valid_version(v: String) -> Bool {\n  let parts = split(v, \".\")\n  if len(parts) > 4 {\n    return false\n  }\n  for p in parts {\n    let cs = split(p, \"\")\n    if len(cs) == 0 || !all_digits(cs) {\n      return false\n    }\n  }\n  return true\n}\n\nfn part_at(ns: List[Int], i: Int) -> Int {\n  return ns\n    |> drop(i)\n    |> first()\n    |> unwrap_or(0)\n}\n\nfn sign(d: Int) -> Int {\n  if d < 0 {\n    return -1\n  }\n  return 1\n}\n\nfn compare_versions(a: String, b: String) -> Result[Int, String] {\n  if !valid_version(a) {\n    return Err(\"bad version: \" + a)\n  }\n  if !valid_version(b) {\n    return Err(\"bad version: \" + b)\n  }\n  let x = map(split(a, \".\"), |p| unwrap_or(parse_int(p), 0))\n  let y = map(split(b, \".\"), |p| unwrap_or(parse_int(p), 0))\n  let diffs = filter(map(range(0, 4), |i| part_at(x, i) - part_at(y, i)), |d| d != 0)\n  return match first(diffs) {\n    Some(d) => Ok(sign(d)),\n    None => Ok(0),\n  }\n}\n",
  parse_money: "fn all_digits(cs: List[String]) -> Bool {\n  return len(filter(cs, |c| c >= \"0\" && c <= \"9\")) == len(cs)\n}\n\nfn dollars_ok(d: String) -> Bool {\n  let groups = split(d, \",\")\n  let plain = split(join(groups, \"\"), \"\")\n  if len(plain) == 0 || !all_digits(plain) {\n    return false\n  }\n  if len(plain) > 1 && unwrap_or(first(plain), \"\") == \"0\" {\n    return false\n  }\n  if len(groups) == 1 {\n    return true\n  }\n  let g0 = groups\n    |> first()\n    |> unwrap_or(\"\")\n    |> str_len()\n  if g0 < 1 || g0 > 3 {\n    return false\n  }\n  for g in drop(groups, 1) {\n    if str_len(g) != 3 {\n      return false\n    }\n  }\n  return true\n}\n\nfn parse_money(s: String) -> Result[Int, String] {\n  let cs = split(s, \"\")\n  let neg = unwrap_or(first(cs), \"\") == \"-\"\n  var rest = cs\n  if neg {\n    rest = drop(cs, 1)\n  }\n  if unwrap_or(first(rest), \"\") != \"$\" {\n    return Err(\"missing $\")\n  }\n  let pieces = rest\n    |> drop(1)\n    |> join(\"\")\n    |> split(\".\")\n  let dollars = unwrap_or(first(pieces), \"\")\n  var cents = 0\n  if len(pieces) > 1 {\n    let after = join(drop(pieces, 1), \".\")\n    let ccs = split(after, \"\")\n    if len(ccs) != 2 || !all_digits(ccs) {\n      return Err(\"bad cents\")\n    }\n    cents = unwrap_or(parse_int(after), 0)\n  }\n  if !dollars_ok(dollars) {\n    return Err(\"bad dollars\")\n  }\n  let total = (dollars |> split(\",\") |> join(\"\") |> parse_int() |> unwrap_or(0)) * 100 + cents\n  if neg {\n    return Ok(0 - total)\n  }\n  return Ok(total)\n}\n",
  eval_expr: "fn at(cs: List[String], i: Int) -> String {\n  return cs\n    |> drop(i)\n    |> first()\n    |> unwrap_or(\"\")\n}\n\nfn is_digit(c: String) -> Bool {\n  return str_len(c) == 1 && c >= \"0\" && c <= \"9\"\n}\n\nfn unexpected(cs: List[String], i: Int) -> String {\n  if i >= len(cs) {\n    return \"unexpected end\"\n  }\n  return \"unexpected character: \" + at(cs, i)\n}\n\nfn factor(cs: List[String], i: Int) -> Result[(Int, Int, Bool), String] {\n  if at(cs, i) == \"(\" {\n    let r = try expr(cs, i + 1)\n    if at(cs, r.1) != \")\" {\n      return Err(unexpected(cs, r.1))\n    }\n    return Ok((r.0, r.1 + 1, r.2))\n  }\n  if !is_digit(at(cs, i)) {\n    return Err(unexpected(cs, i))\n  }\n  var j = i\n  var n = 0\n  while is_digit(at(cs, j)) {\n    n = n * 10 + (cs |> at(j) |> parse_int() |> unwrap_or(0))\n    j = j + 1\n  }\n  return Ok((n, j, false))\n}\n\nfn term(cs: List[String], i: Int) -> Result[(Int, Int, Bool), String] {\n  let f = try factor(cs, i)\n  var v = f.0\n  var j = f.1\n  var z = f.2\n  while at(cs, j) == \"*\" || at(cs, j) == \"/\" {\n    let op = at(cs, j)\n    let g = try factor(cs, j + 1)\n    if op == \"*\" {\n      v = v * g.0\n    } else if g.0 == 0 {\n      z = true\n      v = 0\n    } else {\n      v = v / g.0\n    }\n    z = z || g.2\n    j = g.1\n  }\n  return Ok((v, j, z))\n}\n\nfn expr(cs: List[String], i: Int) -> Result[(Int, Int, Bool), String] {\n  let f = try term(cs, i)\n  var v = f.0\n  var j = f.1\n  var z = f.2\n  while at(cs, j) == \"+\" || at(cs, j) == \"-\" {\n    let op = at(cs, j)\n    let g = try term(cs, j + 1)\n    if op == \"+\" {\n      v = v + g.0\n    } else {\n      v = v - g.0\n    }\n    z = z || g.2\n    j = g.1\n  }\n  return Ok((v, j, z))\n}\n\nfn eval_expr(s: String) -> Result[Int, String] {\n  let cs = filter(split(s, \"\"), |c| c != \" \")\n  let r = try expr(cs, 0)\n  if r.1 < len(cs) {\n    return Err(unexpected(cs, r.1))\n  }\n  if r.2 {\n    return Err(\"division by zero\")\n  }\n  return Ok(r.0)\n}\n",
  tokenize: "type Token =\n  | Num(value: Int)\n  | Ident(name: String)\n  | Sym(text: String)\n\nfn at(cs: List[String], i: Int) -> String {\n  return cs\n    |> drop(i)\n    |> first()\n    |> unwrap_or(\"\")\n}\n\nfn is_digit(c: String) -> Bool {\n  return str_len(c) == 1 && c >= \"0\" && c <= \"9\"\n}\n\nfn is_start(c: String) -> Bool {\n  return str_len(c) == 1 && (c >= \"a\" && c <= \"z\" || c == \"_\")\n}\n\nfn tokenize(s: String) -> Result[List[Token], String] {\n  let cs = split(s, \"\")\n  let n = len(cs)\n  var i = 0\n  var out = []\n  while i < n {\n    let c = at(cs, i)\n    let two = c + at(cs, i + 1)\n    if c == \" \" {\n      i = i + 1\n    } else if is_digit(c) {\n      var v = 0\n      while is_digit(at(cs, i)) {\n        v = v * 10 + (cs |> at(i) |> parse_int() |> unwrap_or(0))\n        i = i + 1\n      }\n      out = append(out, Num(v))\n    } else if is_start(c) {\n      var name = \"\"\n      while is_start(at(cs, i)) || is_digit(at(cs, i)) {\n        name = name + at(cs, i)\n        i = i + 1\n      }\n      out = append(out, Ident(name))\n    } else if contains([\"==\", \"<=\", \">=\", \"!=\"], two) {\n      out = append(out, Sym(two))\n      i = i + 2\n    } else if contains([\"+\", \"-\", \"*\", \"/\", \"=\", \"<\", \">\", \"(\", \")\", \",\"], c) {\n      out = append(out, Sym(c))\n      i = i + 1\n    } else {\n      return Err(\"unexpected character: \" + c + \" at \" + to_string(i))\n    }\n  }\n  return Ok(out)\n}\n",
  parse_config: "type Setting {\n  section: String,\n  key: String,\n  value: String,\n}\n\nfn upsert(xs: List[Setting], s: Setting) -> List[Setting] {\n  var found = false\n  var out = []\n  for x in xs {\n    if x.section == s.section && x.key == s.key {\n      out = append(out, s)\n      found = true\n    } else {\n      out = append(out, x)\n    }\n  }\n  if !found {\n    out = append(out, s)\n  }\n  return out\n}\n\nfn parse_config(lines: List[String]) -> Result[List[Setting], String] {\n  var out = []\n  var section = \"\"\n  for p in enumerate(lines) {\n    let line = trim(p.1)\n    let tag = \"line \" + to_string(p.0 + 1) + \": \"\n    let cs = split(line, \"\")\n    let head = unwrap_or(first(cs), \"\")\n    if head == \"[\" {\n      let inner = cs\n        |> drop(1)\n        |> take(len(cs) - 2)\n        |> join(\"\")\n        |> trim()\n      if len(cs) < 2 || unwrap_or(last(cs), \"\") != \"]\" || inner == \"\" {\n        return Err(tag + \"bad header\")\n      }\n      section = inner\n    } else if line != \"\" && head != \"#\" {\n      let parts = split(line, \"=\")\n      if len(parts) < 2 {\n        return Err(tag + \"missing =\")\n      }\n      let key = parts\n        |> first()\n        |> unwrap_or(\"\")\n        |> trim()\n      if key == \"\" {\n        return Err(tag + \"empty key\")\n      }\n      let value = parts\n        |> drop(1)\n        |> join(\"=\")\n        |> trim()\n      out = upsert(out, Setting { section: section, key: key, value: value })\n    }\n  }\n  return Ok(out)\n}\n",
  bracket_depth: "fn closer(c: String) -> String {\n  return match c {\n    \"(\" => \")\",\n    \"[\" => \"]\",\n    \"{\" => \"}\",\n    _ => \"\",\n  }\n}\n\nfn bracket_depth(s: String) -> Result[Int, String] {\n  var stack = []\n  var best = 0\n  for p in enumerate(split(s, \"\")) {\n    let c = p.1\n    if closer(c) != \"\" {\n      stack = append(stack, closer(c))\n      best = max(best, len(stack))\n    } else if c == \")\" || c == \"]\" || c == \"}\" {\n      if unwrap_or(last(stack), \"\") != c {\n        return Err(\"mismatch at \" + to_string(p.0))\n      }\n      stack = take(stack, len(stack) - 1)\n    }\n  }\n  if len(stack) > 0 {\n    return Err(\"unclosed at end\")\n  }\n  return Ok(best)\n}\n",
  parse_query: "fn decode(s: String) -> String {\n  return join(split(s, \"+\"), \" \")\n}\n\nfn parse_query(s: String) -> Result[List[(String, String)], String] {\n  var out = []\n  for item in split(s, \"&\") {\n    if item != \"\" {\n      let parts = split(item, \"=\")\n      let key = parts\n        |> first()\n        |> unwrap_or(\"\")\n        |> decode()\n      let value = parts\n        |> drop(1)\n        |> join(\"=\")\n        |> decode()\n      if key == \"\" {\n        return Err(\"empty key: \" + item)\n      }\n      out = append(out, (key, value))\n    }\n  }\n  return Ok(out)\n}\n",
  flatten_nested: "fn at(cs: List[String], i: Int) -> String {\n  return cs\n    |> drop(i)\n    |> first()\n    |> unwrap_or(\"\")\n}\n\nfn is_digit(c: String) -> Bool {\n  return str_len(c) == 1 && c >= \"0\" && c <= \"9\"\n}\n\nfn bad(i: Int) -> String {\n  return \"invalid at \" + to_string(i)\n}\n\nfn parse_int_at(cs: List[String], i: Int) -> Result[(Int, Int), String] {\n  var j = i\n  var sign = 1\n  if at(cs, j) == \"-\" {\n    sign = -1\n    j = j + 1\n  }\n  if !is_digit(at(cs, j)) {\n    return Err(bad(j))\n  }\n  var v = 0\n  while is_digit(at(cs, j)) {\n    v = v * 10 + (cs |> at(j) |> parse_int() |> unwrap_or(0))\n    j = j + 1\n  }\n  return Ok((sign * v, j))\n}\n\nfn parse_list(cs: List[String], i: Int, depth: Int) -> Result[(List[Int], Int, Int), String] {\n  if at(cs, i) != \"[\" {\n    return Err(bad(i))\n  }\n  var j = i + 1\n  var ints = []\n  var deepest = depth\n  if at(cs, j) == \"]\" {\n    return Ok((ints, j + 1, deepest))\n  }\n  var going = true\n  while going {\n    if at(cs, j) == \"[\" {\n      let r = try parse_list(cs, j, depth + 1)\n      ints = fold(r.0, ints, |acc, x| append(acc, x))\n      deepest = max(deepest, r.2)\n      j = r.1\n    } else {\n      let r = try parse_int_at(cs, j)\n      ints = append(ints, r.0)\n      j = r.1\n    }\n    if at(cs, j) == \",\" {\n      j = j + 1\n    } else if at(cs, j) == \"]\" {\n      going = false\n    } else {\n      return Err(bad(j))\n    }\n  }\n  return Ok((ints, j + 1, deepest))\n}\n\nfn flatten_nested(s: String) -> Result[(List[Int], Int), String] {\n  let cs = filter(split(s, \"\"), |c| c != \" \")\n  let r = try parse_list(cs, 0, 1)\n  if r.1 < len(cs) {\n    return Err(bad(r.1))\n  }\n  return Ok((r.0, r.2))\n}\n",
  vending_machine: "type Event =\n  | Coin(cents: Int)\n  | Select(price: Int)\n  | Refund\n\nfn vending_machine(events: List[Event]) -> List[String] {\n  var out = []\n  var credit = 0\n  for e in events {\n    let coin = match e {\n      Coin(c) => c,\n      _ => -1,\n    }\n    let price = match e {\n      Select(p) => p,\n      _ => -1,\n    }\n    if coin >= 0 {\n      if contains([5, 10, 25, 100], coin) {\n        credit = credit + coin\n      } else {\n        out = append(out, \"reject \" + to_string(coin))\n      }\n    } else if price >= 0 {\n      if credit >= price {\n        out = append(out, \"vend \" + to_string(price) + \" change \" + to_string(credit - price))\n        credit = 0\n      } else {\n        out = append(out, \"insufficient \" + to_string(credit))\n      }\n    } else if credit > 0 {\n      out = append(out, \"refund \" + to_string(credit))\n      credit = 0\n    }\n  }\n  if credit > 0 {\n    out = append(out, \"refund \" + to_string(credit))\n  }\n  return out\n}\n",
  door_lock: "type Key =\n  | Digit(d: Int)\n  | Enter\n  | Clear\n\nfn door_lock(code: String, events: List[Key]) -> String {\n  var state = \"locked\"\n  var buf = \"\"\n  var fails = 0\n  let size = str_len(code)\n  for k in events {\n    let kind = match k {\n      Digit(_) => \"digit\",\n      Enter => \"enter\",\n      Clear => \"clear\",\n    }\n    let digit = match k {\n      Digit(d) => to_string(d),\n      _ => \"\",\n    }\n    if state == \"open\" {\n      if kind == \"enter\" {\n        state = \"locked\"\n        buf = \"\"\n      }\n    } else if state == \"locked\" {\n      if kind == \"digit\" {\n        buf = buf + digit\n        if str_len(buf) > size {\n          buf = buf\n            |> split(\"\")\n            |> drop(str_len(buf) - size)\n            |> join(\"\")\n        }\n      } else if kind == \"clear\" {\n        buf = \"\"\n      } else {\n        if buf == code {\n          state = \"open\"\n          fails = 0\n        } else {\n          fails = fails + 1\n          if fails >= 3 {\n            state = \"blocked\"\n          }\n        }\n        buf = \"\"\n      }\n    }\n  }\n  return state\n}\n",
  stack_vm: "type Instr =\n  | Push(n: Int)\n  | Pop\n  | Add\n  | Sub\n  | Mul\n  | Dup\n  | Swap\n  | Jz(target: Int)\n  | Jmp(target: Int)\n  | Print\n  | Halt\n\nfn needs(ins: Instr) -> Int {\n  return match ins {\n    Push(_) => 0,\n    Pop => 1,\n    Add => 2,\n    Sub => 2,\n    Mul => 2,\n    Dup => 1,\n    Swap => 2,\n    Jz(_) => 1,\n    Jmp(_) => 0,\n    Print => 1,\n    Halt => 0,\n  }\n}\n\nfn jump_target(ins: Instr) -> Option[Int] {\n  return match ins {\n    Jz(t) => Some(t),\n    Jmp(t) => Some(t),\n    _ => None,\n  }\n}\n\nfn stack_vm(prog: List[Instr]) -> Result[List[Int], String] {\n  let n = len(prog)\n  var stack = []\n  var out = []\n  var pc = 0\n  var steps = 0\n  while pc < n {\n    if steps == 1000 {\n      return Err(\"step limit exceeded\")\n    }\n    steps = steps + 1\n    let ins = prog\n      |> drop(pc)\n      |> first()\n      |> unwrap_or(Halt)\n    let size = len(stack)\n    if size < needs(ins) {\n      return Err(\"stack underflow at \" + to_string(pc))\n    }\n    let target = unwrap_or(jump_target(ins), 0)\n    if target < 0 || target >= n {\n      return Err(\"bad jump at \" + to_string(pc))\n    }\n    let b = unwrap_or(last(stack), 0)\n    let a = stack\n      |> take(size - 1)\n      |> last()\n      |> unwrap_or(0)\n    let rest1 = take(stack, size - 1)\n    let rest2 = take(stack, size - 2)\n    stack = match ins {\n      Push(v) => append(stack, v),\n      Pop => rest1,\n      Add => append(rest2, a + b),\n      Sub => append(rest2, a - b),\n      Mul => append(rest2, a * b),\n      Dup => append(stack, b),\n      Swap => append(append(rest2, b), a),\n      Jz(_) => rest1,\n      Jmp(_) => stack,\n      Print => rest1,\n      Halt => stack,\n    }\n    if ins == Print {\n      out = append(out, b)\n    }\n    pc = match ins {\n      Jz(t) => if_zero(b, t, pc + 1),\n      Jmp(t) => t,\n      Halt => n,\n      _ => pc + 1,\n    }\n  }\n  return Ok(out)\n}\n\nfn if_zero(v: Int, yes: Int, no: Int) -> Int {\n  if v == 0 {\n    return yes\n  }\n  return no\n}\n",
  text_editor: "type EditOp =\n  | Insert(text: String)\n  | Delete(n: Int)\n  | Left(n: Int)\n  | Right(n: Int)\n  | Undo\n\ntype Editor {\n  text: String,\n  cur: Int,\n  history: List[(String, Int)],\n}\n\nfn step(e: Editor, op: EditOp) -> Editor {\n  let cs = split(e.text, \"\")\n  let saved = append(e.history, (e.text, e.cur))\n  return match op {\n    Insert(t) => insert(e, t, saved),\n    Delete(n) => delete(e, min(n, e.cur), saved),\n    Left(n) => Editor { text: e.text, cur: max(0, e.cur - n), history: e.history },\n    Right(n) => Editor { text: e.text, cur: min(len(cs), e.cur + n), history: e.history },\n    Undo => undo(e),\n  }\n}\n\nfn insert(e: Editor, t: String, saved: List[(String, Int)]) -> Editor {\n  let cs = split(e.text, \"\")\n  let text = join(take(cs, e.cur), \"\") + t + join(drop(cs, e.cur), \"\")\n  return Editor { text: text, cur: e.cur + str_len(t), history: saved }\n}\n\nfn delete(e: Editor, k: Int, saved: List[(String, Int)]) -> Editor {\n  let cs = split(e.text, \"\")\n  let text = join(take(cs, e.cur - k), \"\") + join(drop(cs, e.cur), \"\")\n  return Editor { text: text, cur: e.cur - k, history: saved }\n}\n\nfn undo(e: Editor) -> Editor {\n  let n = len(e.history)\n  return match last(e.history) {\n    Some(p) => Editor { text: p.0, cur: p.1, history: take(e.history, n - 1) },\n    None => e,\n  }\n}\n\nfn text_editor(ops: List[EditOp]) -> String {\n  let start = Editor { text: \"\", cur: 0, history: [] }\n  return fold(ops, start, |e, op| step(e, op)).text\n}\n",
  order_states: "type OrderEvent =\n  | Create(id: String)\n  | Pay(id: String)\n  | Ship(id: String)\n  | Cancel(id: String)\n\nfn verb_of(e: OrderEvent) -> (String, String) {\n  return match e {\n    Create(id) => (\"create\", id),\n    Pay(id) => (\"pay\", id),\n    Ship(id) => (\"ship\", id),\n    Cancel(id) => (\"cancel\", id),\n  }\n}\n\nfn allowed(verb: String, state: String) -> Bool {\n  let pay = verb == \"pay\" && state == \"created\"\n  let ship = verb == \"ship\" && state == \"paid\"\n  let cancel = verb == \"cancel\" && (state == \"created\" || state == \"paid\")\n  return pay || ship || cancel\n}\n\nfn target(verb: String) -> String {\n  return match verb {\n    \"pay\" => \"paid\",\n    \"ship\" => \"shipped\",\n    _ => \"cancelled\",\n  }\n}\n\nfn order_states(events: List[OrderEvent]) -> Result[List[(String, String)], String] {\n  var orders = []\n  for e in events {\n    let vi = verb_of(e)\n    let verb = vi.0\n    let id = vi.1\n    let found = find(orders, id)\n    if verb == \"create\" {\n      if len(found) > 0 {\n        return Err(\"duplicate order: \" + id)\n      }\n      orders = append(orders, (id, \"created\"))\n    } else {\n      if len(found) == 0 {\n        return Err(\"unknown order: \" + id)\n      }\n      let state = unwrap_or(first(found), (\"\", \"\")).1\n      if !allowed(verb, state) {\n        return Err(\"cannot \" + verb + \" \" + id + \" from \" + state)\n      }\n      let next = target(verb)\n      orders = map(orders, |o| set_state(o, id, next))\n    }\n  }\n  return Ok(sort_by(orders, |o| o.0))\n}\n\nfn set_state(o: (String, String), id: String, state: String) -> (String, String) {\n  if o.0 == id {\n    return (id, state)\n  }\n  return o\n}\n\nfn find(orders: List[(String, String)], id: String) -> List[(String, String)] {\n  return filter(orders, |o| o.0 == id)\n}\n",
  robot_walk: "type Cmd =\n  | Forward(steps: Int)\n  | TurnLeft\n  | TurnRight\n\nfn delta(d: Int) -> (Int, Int) {\n  return match d {\n    0 => (0, 1),\n    1 => (1, 0),\n    2 => (0, -1),\n    _ => (-1, 0),\n  }\n}\n\nfn robot_walk(cmds: List[Cmd], obstacles: List[(Int, Int)]) -> (Int, Int, String) {\n  var x = 0\n  var y = 0\n  var d = 0\n  for c in cmds {\n    let steps = match c {\n      Forward(k) => k,\n      _ => 0,\n    }\n    d = match c {\n      TurnLeft => (d + 3) % 4,\n      TurnRight => (d + 1) % 4,\n      _ => d,\n    }\n    let dv = delta(d)\n    var k = 0\n    while k < steps {\n      let next = (x + dv.0, y + dv.1)\n      if contains(obstacles, next) {\n        k = steps\n      } else {\n        x = next.0\n        y = next.1\n        k = k + 1\n      }\n    }\n  }\n  let names = [\"N\", \"E\", \"S\", \"W\"]\n  return (x, y, names |> drop(d) |> first() |> unwrap_or(\"N\"))\n}\n",
  bank_ledger: "type BankOp =\n  | Open(name: String)\n  | Deposit(name: String, amount: Int)\n  | Withdraw(name: String, amount: Int)\n  | Transfer(src: String, dst: String, amount: Int)\n\nfn balance(accts: List[(String, Int)], name: String) -> Option[Int] {\n  return accts\n    |> filter(|a| a.0 == name)\n    |> map(|a| a.1)\n    |> first()\n}\n\nfn adjust(accts: List[(String, Int)], name: String, delta: Int) -> List[(String, Int)] {\n  return map(accts, |a| add_if(a, name, delta))\n}\n\nfn add_if(a: (String, Int), name: String, delta: Int) -> (String, Int) {\n  if a.0 == name {\n    return (a.0, a.1 + delta)\n  }\n  return a\n}\n\nfn check(accts: List[(String, Int)], op: BankOp) -> Option[String] {\n  let kind = match op {\n    Open(_) => \"open\",\n    Deposit(_, _) => \"deposit\",\n    Withdraw(_, _) => \"withdraw\",\n    Transfer(_, _, _) => \"transfer\",\n  }\n  let src = match op {\n    Open(n) => n,\n    Deposit(n, _) => n,\n    Withdraw(n, _) => n,\n    Transfer(s, _, _) => s,\n  }\n  let dst = match op {\n    Transfer(_, t, _) => t,\n    _ => src,\n  }\n  let amount = match op {\n    Open(_) => 1,\n    Deposit(_, a) => a,\n    Withdraw(_, a) => a,\n    Transfer(_, _, a) => a,\n  }\n  let src_bal = balance(accts, src)\n  if kind == \"open\" {\n    if src_bal != None {\n      return Some(\"duplicate account \" + src)\n    }\n    return None\n  }\n  if src_bal == None {\n    return Some(\"unknown account \" + src)\n  }\n  if balance(accts, dst) == None {\n    return Some(\"unknown account \" + dst)\n  }\n  if kind == \"transfer\" && src == dst {\n    return Some(\"same account\")\n  }\n  if amount <= 0 {\n    return Some(\"invalid amount\")\n  }\n  if kind != \"deposit\" && amount > unwrap_or(src_bal, 0) {\n    return Some(\"insufficient funds\")\n  }\n  return None\n}\n\nfn apply(accts: List[(String, Int)], op: BankOp) -> List[(String, Int)] {\n  return match op {\n    Open(n) => append(accts, (n, 0)),\n    Deposit(n, a) => adjust(accts, n, a),\n    Withdraw(n, a) => adjust(accts, n, -a),\n    Transfer(s, t, a) => adjust(adjust(accts, s, -a), t, a),\n  }\n}\n\nfn bank_ledger(ops: List[BankOp]) -> Result[List[(String, Int)], String] {\n  var accts = []\n  for p in enumerate(ops) {\n    let problem = check(accts, p.1)\n    if problem != None {\n      return Err(\"step \" + to_string(p.0 + 1) + \": \" + unwrap_or(problem, \"\"))\n    }\n    accts = apply(accts, p.1)\n  }\n  return Ok(accts)\n}\n",
  parking_fees: "type Park =\n  | Arrive(plate: String, minute: Int)\n  | Leave(plate: String, minute: Int)\n\nfn fee(d: Int) -> Int {\n  if d <= 30 {\n    return 0\n  }\n  return min(1000, 200 * ((d - 30 + 59) / 60))\n}\n\nfn lookup(xs: List[(String, Int)], plate: String) -> Option[Int] {\n  return xs\n    |> filter(|p| p.0 == plate)\n    |> map(|p| p.1)\n    |> first()\n}\n\nfn parking_fees(events: List[Park]) -> List[(String, Int)] {\n  var parked = []\n  var totals = []\n  for e in events {\n    let info = match e {\n      Arrive(p, m) => (true, p, m),\n      Leave(p, m) => (false, p, m),\n    }\n    let plate = info.1\n    let start = lookup(parked, plate)\n    if info.0 {\n      if start == None {\n        parked = append(parked, (plate, info.2))\n      }\n    } else if start != None {\n      parked = filter(parked, |p| p.0 != plate)\n      let cost = fee(info.2 - unwrap_or(start, 0))\n      let before = lookup(totals, plate)\n      if before == None {\n        totals = append(totals, (plate, cost))\n      } else {\n        totals = map(totals, |t| (t.0, t.1 + bump(t.0 == plate, cost)))\n      }\n    }\n  }\n  return sort_by(totals, |t| t.0)\n}\n\nfn bump(yes: Bool, n: Int) -> Int {\n  if yes {\n    return n\n  }\n  return 0\n}\n",
  glob_match: "fn at(cs: List[String], i: Int) -> String {\n  return cs\n    |> drop(i)\n    |> first()\n    |> unwrap_or(\"\")\n}\n\nfn tokens(pattern: String) -> List[(String, String)] {\n  let cs = split(pattern, \"\")\n  let n = len(cs)\n  var out = []\n  var i = 0\n  while i < n {\n    let c = at(cs, i)\n    if c == \"\\\\\" {\n      if i + 1 < n {\n        out = append(out, (\"lit\", at(cs, i + 1)))\n        i = i + 2\n      } else {\n        out = append(out, (\"lit\", \"\\\\\"))\n        i = i + 1\n      }\n    } else {\n      let kind = match c {\n        \"*\" => \"star\",\n        \"?\" => \"any\",\n        _ => \"lit\",\n      }\n      out = append(out, (kind, c))\n      i = i + 1\n    }\n  }\n  return out\n}\n\nfn next_row(row: List[Bool], tok: (String, String), sc: List[String]) -> List[Bool] {\n  var out = []\n  if tok.0 == \"star\" {\n    var acc = false\n    for b in row {\n      acc = acc || b\n      out = append(out, acc)\n    }\n    return out\n  }\n  out = [false]\n  for p in zip(row, sc) {\n    out = append(out, p.0 && (tok.0 == \"any\" || p.1 == tok.1))\n  }\n  return out\n}\n\nfn glob_match(pattern: String, s: String) -> Bool {\n  let sc = split(s, \"\")\n  let start = append(map(sc, |c| false), true)\n  let row = reverse(start)\n  let final_row = fold(tokens(pattern), row, |r, t| next_row(r, t, sc))\n  return unwrap_or(last(final_row), false)\n}\n",
  league_table: "type Match {\n  home: String,\n  away: String,\n  home_goals: Int,\n  away_goals: Int,\n}\n\nfn points(a: Int, b: Int) -> Int {\n  if a > b {\n    return 3\n  }\n  if a == b {\n    return 1\n  }\n  return 0\n}\n\nfn stats(team: String, matches: List[Match]) -> (String, Int, Int, Int) {\n  var pts = 0\n  var gf = 0\n  var ga = 0\n  for m in matches {\n    if m.home == team {\n      gf = gf + m.home_goals\n      ga = ga + m.away_goals\n      pts = pts + points(m.home_goals, m.away_goals)\n    }\n    if m.away == team {\n      gf = gf + m.away_goals\n      ga = ga + m.home_goals\n      pts = pts + points(m.away_goals, m.home_goals)\n    }\n  }\n  return (team, pts, gf - ga, gf)\n}\n\nfn league_table(matches: List[Match]) -> List[(String, Int, Int, Int)] {\n  var teams = []\n  for m in matches {\n    if !contains(teams, m.home) {\n      teams = append(teams, m.home)\n    }\n    if !contains(teams, m.away) {\n      teams = append(teams, m.away)\n    }\n  }\n  return teams\n    |> map(|t| stats(t, matches))\n    |> sort_by(|r| r.0)\n    |> sort_desc_by(|r| r.3)\n    |> sort_desc_by(|r| r.2)\n    |> sort_desc_by(|r| r.1)\n}\n",
  payroll_by_dept: "type Employee {\n  name: String,\n  dept: String,\n  hours: Int,\n  rate_cents: Int,\n}\n\nfn pay(e: Employee) -> Int {\n  if e.hours <= 40 {\n    return e.hours * e.rate_cents\n  }\n  return 40 * e.rate_cents + (e.hours - 40) * e.rate_cents * 3 / 2\n}\n\nfn payroll_by_dept(emps: List[Employee]) -> List[(String, Int)] {\n  return emps\n    |> group_by(|e| e.dept)\n    |> map(|g| (g.0, sum(map(g.1, |e| pay(e)))))\n    |> sort_by(|r| r.0)\n    |> sort_desc_by(|r| r.1)\n}\n",
  build_order: "type Job {\n  name: String,\n  deps: List[String],\n}\n\nfn all_in(xs: List[String], ys: List[String]) -> Bool {\n  return len(filter(xs, |x| !contains(ys, x))) == 0\n}\n\nfn build_order(jobs: List[Job]) -> Result[List[String], String] {\n  var seen = []\n  for j in jobs {\n    if contains(seen, j.name) {\n      return Err(\"duplicate job: \" + j.name)\n    }\n    seen = append(seen, j.name)\n  }\n  for j in jobs {\n    for d in j.deps {\n      if !contains(seen, d) {\n        return Err(\"unknown dependency: \" + d)\n      }\n    }\n  }\n  var done = []\n  while len(done) < len(jobs) {\n    let ready = filter(jobs, |j| !contains(done, j.name) && all_in(j.deps, done))\n    if len(ready) == 0 {\n      return Err(\"cycle detected\")\n    }\n    done = append(done, ready |> map(|j| j.name) |> first() |> unwrap_or(\"\"))\n  }\n  return Ok(done)\n}\n",
  top_product_per_region: "type Sale {\n  region: String,\n  product: String,\n  units: Int,\n  price_cents: Int,\n}\n\nfn best(region: String, sales: List[Sale]) -> (String, String, Int) {\n  let totals = sales\n    |> group_by(|s| s.product)\n    |> map(|g| (g.0, sum(map(g.1, |s| s.units * s.price_cents))))\n    |> sort_by(|p| p.0)\n    |> sort_desc_by(|p| p.1)\n  let top = unwrap_or(first(totals), (\"\", 0))\n  return (region, top.0, top.1)\n}\n\nfn top_product_per_region(sales: List[Sale]) -> List[(String, String, Int)] {\n  return sales\n    |> group_by(|s| s.region)\n    |> sort_by(|g| g.0)\n    |> map(|g| best(g.0, g.1))\n}\n",
  free_slots: "type Meeting {\n  start: Int,\n  end: Int,\n}\n\nfn free_slots(meetings: List[Meeting], day_start: Int, day_end: Int) -> List[(Int, Int)] {\n  let ms = sort_by(filter(meetings, |m| m.end > m.start), |m| m.start)\n  var out = []\n  var cur = day_start\n  for m in ms {\n    let s = min(m.start, day_end)\n    if s > cur {\n      out = append(out, (cur, s))\n    }\n    cur = max(cur, m.end)\n  }\n  if day_end > cur {\n    out = append(out, (cur, day_end))\n  }\n  return out\n}\n",
  invoice_total: "type Line {\n  sku: String,\n  qty: Int,\n  unit_cents: Int,\n}\n\nfn line_amount(l: Line) -> Int {\n  let a = l.qty * l.unit_cents\n  if l.qty >= 10 {\n    return a - a / 10\n  }\n  return a\n}\n\nfn apply_coupon(sub: Int, coupon: String) -> Result[Int, String] {\n  if coupon == \"\" {\n    return Ok(sub)\n  }\n  if coupon == \"SAVE500\" {\n    return Ok(max(sub - 500, 0))\n  }\n  if coupon == \"PCT10\" {\n    return Ok(sub - sub / 10)\n  }\n  if coupon == \"BIG20\" {\n    if sub < 10000 {\n      return Err(\"coupon not applicable: BIG20\")\n    }\n    return Ok(sub - sub / 5)\n  }\n  return Err(\"unknown coupon: \" + coupon)\n}\n\nfn invoice_total(lines: List[Line], coupon: String) -> Result[Int, String] {\n  for l in lines {\n    if l.qty < 1 {\n      return Err(\"bad quantity: \" + l.sku)\n    }\n  }\n  let sub = sum(map(lines, |l| line_amount(l)))\n  let amount = try apply_coupon(sub, coupon)\n  return Ok(amount + (amount * 8 + 50) / 100)\n}\n",
  inventory_ledger: "type Stock {\n  sku: String,\n  qty: Int,\n}\n\ntype Txn {\n  sku: String,\n  delta: Int,\n}\n\nfn update(s: Stock, sku: String, delta: Int) -> Stock {\n  if s.sku == sku {\n    return Stock { sku: s.sku, qty: s.qty + delta }\n  }\n  return s\n}\n\nfn inventory_ledger(stock: List[Stock], txns: List[Txn]) -> Result[List[Stock], String] {\n  var cur = stock\n  for p in enumerate(txns) {\n    let n = to_string(p.0 + 1)\n    let t = p.1\n    let hit = filter(cur, |s| s.sku == t.sku)\n    if len(hit) == 0 {\n      return Err(\"txn \" + n + \": unknown sku \" + t.sku)\n    }\n    let q = sum(map(hit, |s| s.qty)) + t.delta\n    if q < 0 {\n      return Err(\"txn \" + n + \": \" + t.sku + \" would go negative\")\n    }\n    cur = map(cur, |s| update(s, t.sku, t.delta))\n  }\n  let out = sort_by(filter(cur, |s| s.qty > 0), |s| s.sku)\n  return Ok(out)\n}\n",
  student_medians: "type Student {\n  name: String,\n  scores: List[Int],\n}\n\nfn median(xs: List[Int]) -> Float {\n  let s = sort_by(xs, |x| x)\n  let n = len(s)\n  let a = s\n    |> drop((n - 1) / 2)\n    |> first()\n    |> unwrap_or(0)\n  let b = s\n    |> drop(n / 2)\n    |> first()\n    |> unwrap_or(0)\n  return to_float(a + b) / 2.0\n}\n\nfn student_medians(students: List[Student]) -> List[(String, Float)] {\n  return students\n    |> filter(|s| len(s.scores) > 0)\n    |> map(|s| (s.name, median(s.scores)))\n    |> sort_by(|r| r.0)\n    |> sort_desc_by(|r| r.1)\n}\n",
  latency_report: "type Request {\n  endpoint: String,\n  ms: Int,\n  status: Int,\n}\n\nfn summarize(ep: String, rs: List[Request]) -> (String, Int, Int, Int) {\n  let n = len(rs)\n  let k = (9 * n + 9) / 10\n  let sorted = sort_by(map(rs, |r| r.ms), |x| x)\n  let p = sorted\n    |> drop(k - 1)\n    |> first()\n    |> unwrap_or(0)\n  let errs = len(filter(rs, |r| r.status >= 500))\n  return (ep, n, p, errs)\n}\n\nfn latency_report(entries: List[Request]) -> List[(String, Int, Int, Int)] {\n  return map(group_by(entries, |e| e.endpoint), |g| summarize(g.0, g.1))\n}\n",
  competition_rank: "type Player {\n  name: String,\n  score: Int,\n}\n\nfn competition_rank(players: List[Player]) -> List[(Int, String)] {\n  let sorted = sort_desc_by(sort_by(players, |p| p.name), |p| p.score)\n  return map(sorted, |p| (1 + len(filter(players, |q| q.score > p.score)), p.name))\n}\n",
  settle_debts: "type Expense {\n  payer: String,\n  amount_cents: Int,\n}\n\nfn paid(expenses: List[Expense], who: String) -> Int {\n  return expenses\n    |> filter(|e| e.payer == who)\n    |> map(|e| e.amount_cents)\n    |> sum()\n}\n\nfn extra_cent(i: Int, extra: Int) -> Int {\n  if i < extra {\n    return 1\n  }\n  return 0\n}\n\nfn adjust(b: (String, Int), from: String, to: String, amount: Int) -> (String, Int) {\n  if b.0 == from {\n    return (b.0, b.1 + amount)\n  }\n  if b.0 == to {\n    return (b.0, b.1 - amount)\n  }\n  return b\n}\n\nfn settle_debts(expenses: List[Expense], people: List[String]) -> List[(String, String, Int)] {\n  let n = len(people)\n  let total = sum(map(expenses, |e| e.amount_cents))\n  let share = total / n\n  let extra = total % n\n  var bal = map(enumerate(people), |p| (p.1, paid(expenses, p.1) - share - extra_cent(p.0, extra)))\n  var out = []\n  var going = true\n  while going {\n    let debtors = sort_by(filter(bal, |b| b.1 < 0), |b| b.1)\n    let creditors = sort_desc_by(filter(bal, |b| b.1 > 0), |b| b.1)\n    if len(debtors) == 0 || len(creditors) == 0 {\n      going = false\n    } else {\n      let d = unwrap_or(first(debtors), (\"\", 0))\n      let c = unwrap_or(first(creditors), (\"\", 0))\n      let amount = min(-d.1, c.1)\n      out = append(out, (d.0, c.0, amount))\n      bal = map(bal, |b| adjust(b, d.0, c.0, amount))\n    }\n  }\n  return out\n}\n",
  coverage_gaps: "type Shift {\n  worker: String,\n  start_hour: Int,\n  end_hour: Int,\n}\n\nfn on_duty(shifts: List[Shift], h: Int) -> Int {\n  let ws = map(filter(shifts, |s| s.start_hour <= h && h < s.end_hour), |s| s.worker)\n  return len(group_by(ws, |w| w))\n}\n\nfn coverage_gaps(shifts: List[Shift], required: Int) -> List[Int] {\n  return filter(range(0, 24), |h| on_duty(shifts, h) < required)\n}\n",
  session_totals: "type Session {\n  user: String,\n  kind: String,\n  time: Int,\n}\n\nfn user_total(evs: List[Session], end: Int) -> Int {\n  var total = 0\n  var since = 0\n  var inside = false\n  for e in evs {\n    if e.kind == \"login\" && !inside {\n      inside = true\n      since = e.time\n    } else if e.kind == \"logout\" && inside {\n      inside = false\n      total = total + e.time - since\n    }\n  }\n  if inside {\n    total = total + end - since\n  }\n  return total\n}\n\nfn session_totals(events: List[Session]) -> List[(String, Int)] {\n  let end = match last(events) {\n    Some(e) => e.time,\n    None => 0,\n  }\n  return events\n    |> group_by(|e| e.user)\n    |> map(|g| (g.0, user_total(g.1, end)))\n    |> sort_by(|r| r.0)\n}\n",
  merge_contacts: "type Contact {\n  name: String,\n  email: String,\n  phone: String,\n}\n\nfn digits(s: String) -> String {\n  return s\n    |> split(\"\")\n    |> filter(|c| c >= \"0\" && c <= \"9\")\n    |> join(\"\")\n}\n\nfn linked(a: Contact, b: Contact) -> Bool {\n  let ea = trim(a.email)\n  let pa = digits(a.phone)\n  return ea != \"\" && ea == trim(b.email) || pa != \"\" && pa == digits(b.phone)\n}\n\nfn at(xs: List[Int], i: Int) -> Int {\n  return xs\n    |> drop(i)\n    |> first()\n    |> unwrap_or(0)\n}\n\nfn lower(m: Int, c: Contact, q: (Int, Contact), labels: List[Int]) -> Int {\n  if linked(c, q.1) {\n    return min(m, at(labels, q.0))\n  }\n  return m\n}\n\nfn or_else(a: String, b: String) -> String {\n  if a == \"\" {\n    return b\n  }\n  return a\n}\n\nfn fill(a: Contact, c: Contact) -> Contact {\n  let name = or_else(a.name, c.name)\n  let email = or_else(a.email, c.email)\n  return Contact { name: name, email: email, phone: or_else(a.phone, c.phone) }\n}\n\nfn combine(cs: List[Contact]) -> Contact {\n  let base = unwrap_or(first(cs), Contact { name: \"\", email: \"\", phone: \"\" })\n  return fold(drop(cs, 1), base, |a, c| fill(a, c))\n}\n\nfn merge_contacts(contacts: List[Contact]) -> List[Contact] {\n  let idx = enumerate(contacts)\n  var labels = range(0, len(contacts))\n  var changed = true\n  while changed {\n    let cur = labels\n    let next = map(idx, |p| fold(idx, at(cur, p.0), |m, q| lower(m, p.1, q, cur)))\n    changed = next != cur\n    labels = next\n  }\n  return labels\n    |> zip(contacts)\n    |> group_by(|p| p.0)\n    |> map(|g| combine(map(g.1, |p| p.1)))\n}\n",
  age_histogram: "type Person {\n  name: String,\n  age: Int,\n}\n\nfn age_histogram(people: List[Person], width: Int) -> Result[List[(String, Int)], String] {\n  if width < 1 {\n    return Err(\"bad width\")\n  }\n  for p in people {\n    if p.age < 0 {\n      return Err(\"negative age: \" + p.name)\n    }\n  }\n  if len(people) == 0 {\n    return Ok([])\n  }\n  let bs = map(people, |p| p.age / width)\n  let lo = fold(bs, unwrap_or(first(bs), 0), |a, b| min(a, b))\n  let hi = fold(bs, lo, |a, b| max(a, b))\n  let label = |b| to_string(b * width) + \"-\" + to_string(b * width + width - 1)\n  return Ok(map(range(lo, hi + 1), |b| (label(b), len(filter(bs, |x| x == b)))))\n}\n",
  max_subarray: "fn max_subarray(xs: List[Int]) -> Option[(Int, Int, Int)] {\n  if len(xs) == 0 {\n    return None\n  }\n  var best = (unwrap_or(first(xs), 0), 0, 0)\n  for p in enumerate(xs) {\n    var s = 0\n    for q in enumerate(drop(xs, p.0)) {\n      s = s + q.1\n      if s > best.0 {\n        best = (s, p.0, p.0 + q.0)\n      }\n    }\n  }\n  return Some(best)\n}\n",
  lis_length: "fn lis_length(xs: List[Int]) -> (Int, Int) {\n  if len(xs) == 0 {\n    return (0, 0)\n  }\n  var lens = []\n  var cnts = []\n  for x in xs {\n    var l = 1\n    var c = 1\n    for t in zip(xs, zip(lens, cnts)) {\n      let y = t.0\n      let lc = t.1\n      if y < x {\n        if lc.0 + 1 > l {\n          l = lc.0 + 1\n          c = lc.1\n        } else if lc.0 + 1 == l {\n          c = c + lc.1\n        }\n      }\n    }\n    lens = append(lens, l)\n    cnts = append(cnts, c)\n  }\n  let best = fold(lens, 0, |a, b| max(a, b))\n  let total = lens\n    |> zip(cnts)\n    |> filter(|p| p.0 == best)\n    |> map(|p| p.1)\n    |> sum()\n  return (best, total)\n}\n",
  spiral_order: "fn at(xs: List[Int], i: Int) -> Int {\n  return xs\n    |> drop(i)\n    |> first()\n    |> unwrap_or(0)\n}\n\nfn cell(m: List[List[Int]], r: Int, c: Int) -> Int {\n  return m\n    |> drop(r)\n    |> first()\n    |> unwrap_or([])\n    |> at(c)\n}\n\nfn spiral_order(m: List[List[Int]]) -> List[Int] {\n  var out = []\n  let width = m\n    |> first()\n    |> unwrap_or([])\n    |> len()\n  if len(m) == 0 || width == 0 {\n    return out\n  }\n  var top = 0\n  var bottom = len(m) - 1\n  var left = 0\n  var right = width - 1\n  while top <= bottom && left <= right {\n    for r in range(top, bottom + 1) {\n      out = append(out, cell(m, r, left))\n    }\n    for c in range(left + 1, right + 1) {\n      out = append(out, cell(m, bottom, c))\n    }\n    if left < right {\n      for r in reverse(range(top, bottom)) {\n        out = append(out, cell(m, r, right))\n      }\n    }\n    if top < bottom {\n      for c in reverse(range(left + 1, right)) {\n        out = append(out, cell(m, top, c))\n      }\n    }\n    top = top + 1\n    bottom = bottom - 1\n    left = left + 1\n    right = right - 1\n  }\n  return out\n}\n",
  next_permutation: "fn at(xs: List[Int], i: Int) -> Int {\n  return xs\n    |> drop(i)\n    |> first()\n    |> unwrap_or(0)\n}\n\nfn next_permutation(xs: List[Int]) -> List[Int] {\n  var pivot_at = -1\n  for p in enumerate(zip(xs, drop(xs, 1))) {\n    let pair = p.1\n    if pair.0 < pair.1 {\n      pivot_at = p.0\n    }\n  }\n  if pivot_at < 0 {\n    return sort_by(xs, |x| x)\n  }\n  let pivot = at(xs, pivot_at)\n  let suffix = drop(xs, pivot_at + 1)\n  var j = 0\n  for q in enumerate(suffix) {\n    if q.1 > pivot {\n      j = q.0\n    }\n  }\n  let swapped = map(enumerate(suffix), |q| (match q.0 == j {\n    true => pivot,\n    false => q.1,\n  }))\n  var out = append(take(xs, pivot_at), at(suffix, j))\n  for x in reverse(swapped) {\n    out = append(out, x)\n  }\n  return out\n}\n",
  k_most_frequent: "fn k_most_frequent(xs: List[Int], k: Int) -> List[(Int, Int)] {\n  if k <= 0 {\n    return []\n  }\n  let counted = xs\n    |> group_by(|x| x)\n    |> map(|g| (g.0, len(g.1)))\n    |> sort_by(|p| p.0)\n  return take(sort_desc_by(counted, |p| p.1), k)\n}\n",
  sliding_window_max: "fn window_max(w: List[Int]) -> Int {\n  return fold(w, unwrap_or(first(w), 0), |a, b| max(a, b))\n}\n\nfn sliding_window_max(xs: List[Int], k: Int) -> Result[List[Int], String] {\n  if k < 1 {\n    return Err(\"window must be positive\")\n  }\n  if k > len(xs) {\n    return Err(\"window larger than input\")\n  }\n  let out = map(range(0, len(xs) - k + 1), |i| (xs |> drop(i) |> take(k) |> window_max()))\n  return Ok(out)\n}\n",
  min_coins: "fn at(xs: List[Int], i: Int) -> Int {\n  return xs\n    |> drop(i)\n    |> first()\n    |> unwrap_or(0)\n}\n\nfn min_coins(coins: List[Int], amount: Int) -> Option[(Int, List[Int])] {\n  if amount < 0 {\n    return None\n  }\n  var best = [0]\n  for a in range(1, amount + 1) {\n    var b = -1\n    for c in coins {\n      if a - c >= 0 {\n        let p = at(best, a - c)\n        if p >= 0 && (b < 0 || p + 1 < b) {\n          b = p + 1\n        }\n      }\n    }\n    best = append(best, b)\n  }\n  if at(best, amount) < 0 {\n    return None\n  }\n  let desc = sort_desc_by(coins, |c| c)\n  var used = []\n  var a = amount\n  var cap = amount\n  while a > 0 {\n    let rest = a\n    let limit = cap\n    let need = at(best, rest) - 1\n    let pick = first(filter(desc, |c| c <= limit && rest - c >= 0 && at(best, rest - c) == need))\n    let c = unwrap_or(pick, rest)\n    used = append(used, c)\n    a = a - c\n    cap = c\n  }\n  return Some((len(used), used))\n}\n",
  edit_script_distance: "fn at(xs: List[Int], i: Int) -> Int {\n  return xs\n    |> drop(i)\n    |> first()\n    |> unwrap_or(0)\n}\n\nfn ch(xs: List[String], i: Int) -> String {\n  if i < 0 {\n    return \"\"\n  }\n  return xs\n    |> drop(i)\n    |> first()\n    |> unwrap_or(\"\")\n}\n\nfn edit_script_distance(a: String, b: String) -> Int {\n  let ac = split(a, \"\")\n  let bc = split(b, \"\")\n  let m = len(bc)\n  var prev2 = []\n  var prev = range(0, m + 1)\n  for i in range(1, len(ac) + 1) {\n    var cur = [i]\n    for j in range(1, m + 1) {\n      let cost = match ch(ac, i - 1) == ch(bc, j - 1) {\n        true => 0,\n        false => 1,\n      }\n      let left = at(cur, j - 1)\n      var v = min(min(at(prev, j) + 1, left + 1), at(prev, j - 1) + cost)\n      let crossed = ch(ac, i - 1) == ch(bc, j - 2) && ch(ac, i - 2) == ch(bc, j - 1)\n      let swap_ok = i > 1 && j > 1 && crossed\n      if swap_ok {\n        v = min(v, at(prev2, j - 2) + 1)\n      }\n      cur = append(cur, v)\n    }\n    prev2 = prev\n    prev = cur\n  }\n  return at(prev, m)\n}\n",
  bowling_score: "fn at(xs: List[Int], i: Int) -> Int {\n  return xs\n    |> drop(i)\n    |> first()\n    |> unwrap_or(0)\n}\n\nfn bowling_score(rolls: List[Int]) -> Result[Int, String] {\n  if len(filter(rolls, |r| r < 0 || r > 10)) > 0 {\n    return Err(\"invalid roll\")\n  }\n  let n = len(rolls)\n  var i = 0\n  var score = 0\n  for frame in range(1, 10) {\n    if i >= n {\n      return Err(\"incomplete game\")\n    }\n    if at(rolls, i) == 10 {\n      score = score + 10 + at(rolls, i + 1) + at(rolls, i + 2)\n      i = i + 1\n    } else {\n      if i + 1 >= n {\n        return Err(\"incomplete game\")\n      }\n      let pins = at(rolls, i) + at(rolls, i + 1)\n      if pins > 10 {\n        return Err(\"too many pins in frame \" + to_string(frame))\n      }\n      if pins == 10 {\n        score = score + 10 + at(rolls, i + 2)\n      } else {\n        score = score + pins\n      }\n      i = i + 2\n    }\n  }\n  if i + 1 >= n {\n    return Err(\"incomplete game\")\n  }\n  let a = at(rolls, i)\n  let b = at(rolls, i + 1)\n  var tenth = 2\n  if a == 10 {\n    if i + 2 >= n {\n      return Err(\"incomplete game\")\n    }\n    if b != 10 && b + at(rolls, i + 2) > 10 {\n      return Err(\"too many pins in frame 10\")\n    }\n    tenth = 3\n  } else {\n    if a + b > 10 {\n      return Err(\"too many pins in frame 10\")\n    }\n    if a + b == 10 {\n      if i + 2 >= n {\n        return Err(\"incomplete game\")\n      }\n      tenth = 3\n    }\n  }\n  if i + tenth < n {\n    return Err(\"too many rolls\")\n  }\n  return Ok(score + sum(drop(rolls, i)))\n}\n",
  tennis_score: "fn name(n: Int) -> String {\n  return match n {\n    0 => \"love\",\n    1 => \"15\",\n    2 => \"30\",\n    _ => \"40\",\n  }\n}\n\nfn tennis_score(points: String) -> String {\n  var a = 0\n  var b = 0\n  var over = false\n  for c in split(points, \"\") {\n    if over {\n      return \"error: point after game\"\n    }\n    if c == \"A\" {\n      a = a + 1\n    } else if c == \"B\" {\n      b = b + 1\n    } else {\n      return \"error: bad point\"\n    }\n    if (a >= 4 || b >= 4) && abs(a - b) >= 2 {\n      over = true\n    }\n  }\n  if over {\n    if a > b {\n      return \"game A\"\n    }\n    return \"game B\"\n  }\n  if a >= 3 && b >= 3 {\n    if a == b {\n      return \"deuce\"\n    }\n    if a > b {\n      return \"advantage A\"\n    }\n    return \"advantage B\"\n  }\n  if a == b {\n    return name(a) + \"-all\"\n  }\n  return name(a) + \"-\" + name(b)\n}\n",
  life_step: "fn cell(g: List[List[String]], r: Int, c: Int) -> String {\n  if r < 0 || c < 0 {\n    return \".\"\n  }\n  let row = g\n    |> drop(r)\n    |> first()\n    |> unwrap_or([])\n  return row\n    |> drop(c)\n    |> first()\n    |> unwrap_or(\".\")\n}\n\nfn live_around(g: List[List[String]], r: Int, c: Int) -> Int {\n  var n = 0\n  for dr in [-1, 0, 1] {\n    for dc in [-1, 0, 1] {\n      if (dr != 0 || dc != 0) && cell(g, r + dr, c + dc) == \"#\" {\n        n = n + 1\n      }\n    }\n  }\n  return n\n}\n\nfn next_cell(g: List[List[String]], r: Int, c: Int, here: String) -> String {\n  let n = live_around(g, r, c)\n  if n == 3 || here == \"#\" && n == 2 {\n    return \"#\"\n  }\n  return \".\"\n}\n\nfn life_step(grid: List[String], steps: Int) -> List[String] {\n  var g = map(grid, |row| split(row, \"\"))\n  var s = 0\n  while s < steps {\n    let cur = g\n    g = map(enumerate(cur), |rp| map(enumerate(rp.1), |cp| next_cell(cur, rp.0, cp.0, cp.1)))\n    s = s + 1\n  }\n  return map(g, |row| join(row, \"\"))\n}\n",
  tic_tac_toe: "fn mark(cells: List[String], i: Int) -> String {\n  return cells\n    |> drop(i)\n    |> first()\n    |> unwrap_or(\"\")\n}\n\nfn has_line(cells: List[String], p: String) -> Bool {\n  let rows = [[0, 1, 2], [3, 4, 5], [6, 7, 8]]\n  let cols_diags = [[0, 3, 6], [1, 4, 7], [2, 5, 8], [0, 4, 8], [2, 4, 6]]\n  let lines = fold(cols_diags, rows, |acc, l| append(acc, l))\n  let full = filter(lines, |l| len(filter(l, |i| mark(cells, i) == p)) == 3)\n  return len(full) > 0\n}\n\nfn tic_tac_toe(board: List[String]) -> String {\n  let cells = split(join(board, \"\"), \"\")\n  let nx = len(filter(cells, |c| c == \"X\"))\n  let no = len(filter(cells, |c| c == \"O\"))\n  let xw = has_line(cells, \"X\")\n  let ow = has_line(cells, \"O\")\n  if nx != no && nx != no + 1 {\n    return \"invalid\"\n  }\n  if xw && ow {\n    return \"invalid\"\n  }\n  if xw && nx != no + 1 {\n    return \"invalid\"\n  }\n  if ow && nx != no {\n    return \"invalid\"\n  }\n  if xw {\n    return \"X wins\"\n  }\n  if ow {\n    return \"O wins\"\n  }\n  if nx + no == 9 {\n    return \"draw\"\n  }\n  return \"in progress\"\n}\n",
  poker_hand: "fn rank_of(r: String) -> Int {\n  let found = filter(enumerate(split(\"23456789TJQKA\", \"\")), |p| p.1 == r)\n  return match first(found) {\n    Some(p) => p.0,\n    None => -1,\n  }\n}\n\nfn card_rank(c: String) -> Int {\n  return c\n    |> split(\"\")\n    |> first()\n    |> unwrap_or(\"\")\n    |> rank_of()\n}\n\nfn valid_card(c: String) -> Bool {\n  let parts = split(c, \"\")\n  let r = unwrap_or(first(parts), \"\")\n  let s = unwrap_or(last(parts), \"\")\n  return len(parts) == 2 && rank_of(r) >= 0 && contains([\"C\", \"D\", \"H\", \"S\"], s)\n}\n\nfn poker_hand(cards: List[String]) -> String {\n  if len(cards) != 5 || len(group_by(cards, |c| c)) != 5 {\n    return \"invalid\"\n  }\n  if len(filter(cards, |c| !valid_card(c))) > 0 {\n    return \"invalid\"\n  }\n  let ranks = sort_by(map(cards, |c| card_rank(c)), |r| r)\n  let suits = map(cards, |c| (c |> split(\"\") |> last() |> unwrap_or(\"\")))\n  let flush = len(group_by(suits, |s| s)) == 1\n  let counts = ranks\n    |> group_by(|r| r)\n    |> map(|g| len(g.1))\n    |> sort_desc_by(|n| n)\n  let spread = unwrap_or(last(ranks), 0) - unwrap_or(first(ranks), 0)\n  let straight = len(counts) == 5 && (spread == 4 || ranks == [0, 1, 2, 3, 12])\n  let top = unwrap_or(first(counts), 0)\n  let second = counts\n    |> drop(1)\n    |> first()\n    |> unwrap_or(0)\n  if straight && flush {\n    return \"straight flush\"\n  }\n  if top == 4 {\n    return \"four of a kind\"\n  }\n  if top == 3 && second == 2 {\n    return \"full house\"\n  }\n  if flush {\n    return \"flush\"\n  }\n  if straight {\n    return \"straight\"\n  }\n  if top == 3 {\n    return \"three of a kind\"\n  }\n  if top == 2 && second == 2 {\n    return \"two pair\"\n  }\n  if top == 2 {\n    return \"one pair\"\n  }\n  return \"high card\"\n}\n",
  count_islands: "fn key(r: Int, c: Int) -> Int {\n  return r * 1000 + c\n}\n\nfn count_islands(grid: List[String]) -> (Int, Int) {\n  var cells = []\n  for rp in enumerate(grid) {\n    for cp in enumerate(split(rp.1, \"\")) {\n      if cp.1 == \"#\" {\n        cells = append(cells, (rp.0, cp.0))\n      }\n    }\n  }\n  var seen = map_from(map(cells, |p| (key(p.0, p.1), false)))\n  var count = 0\n  var largest = 0\n  for start in cells {\n    if map_get(seen, key(start.0, start.1)) == Some(false) {\n      count = count + 1\n      seen = map_set(seen, key(start.0, start.1), true)\n      var stack = [start]\n      var size = 0\n      while len(stack) > 0 {\n        let top = unwrap_or(last(stack), start)\n        stack = take(stack, len(stack) - 1)\n        size = size + 1\n        let vertical = [(top.0 + 1, top.1), (top.0 - 1, top.1)]\n        let around = append(append(vertical, (top.0, top.1 + 1)), (top.0, top.1 - 1))\n        for nb in around {\n          let k = key(nb.0, nb.1)\n          if nb.0 >= 0 && nb.1 >= 0 && map_get(seen, k) == Some(false) {\n            seen = map_set(seen, k, true)\n            stack = append(stack, nb)\n          }\n        }\n      }\n      largest = max(largest, size)\n    }\n  }\n  return (count, largest)\n}\n",
  elevator_scan: "fn elevator_scan(start: Int, requests: List[Int], direction: String) -> List[Int] {\n  let floors = map(group_by(requests, |f| f), |g| g.0)\n  let above = sort_by(filter(floors, |f| f > start), |f| f)\n  let below = sort_desc_by(filter(floors, |f| f < start), |f| f)\n  var out = filter(floors, |f| f == start)\n  var rest = below\n  if direction == \"up\" {\n    for f in above {\n      out = append(out, f)\n    }\n  } else {\n    rest = above\n    for f in below {\n      out = append(out, f)\n    }\n  }\n  for f in rest {\n    out = append(out, f)\n  }\n  return out\n}\n",
};
